agg=json.loads((R/'aggregate.json').read_text()); summary=json.loads((R/'summary.json').read_text()); validity=json.loads((R/'trial-validity.json').read_text())
def a(backend,rev,scenario,n,op='cleanup',subset='all'):
 return next(x for x in agg if (x['backend'],x['revision'],x['scenario'],x['rows'],x['operation'],x['subset'])==(backend,rev,scenario,n,op,subset))
def s(backend,rev,trial,scenario,n,op='cleanup',subset='all'):
 return next(x for x in summary if (x['backend'],x['revision'],x['trial'],x['scenario'],x['rows'],x['operation'],x['subset'])==(backend,rev,trial,scenario,n,op,subset))
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def link(name):return f'[{name}]({P/name})'
