resources=[]
for v in validity:
 path=R/f"{v['backend']}-{v['revision']}-trial{v['trial']}.resources.jsonl"
 xs=[json.loads(x) for x in path.read_text().splitlines()]
 pi=[y['pswpin']-x['pswpin'] for x,y in zip(xs,xs[1:])]
 cpu=[];psi=[];psi_total={};last=None
 for x in xs:
  for line in x.get('memory_psi','').splitlines():
   parts=line.split(); d=dict(i.split('=') for i in parts[1:]);psi.append(float(d['avg10']));psi_total.setdefault(parts[0],[]).append(int(d['total']))
  usage=sum(int(dict(line.split() for line in c['cpu.stat'].splitlines())['usage_usec']) for c in x.get('containers',{}).values())
