 row={**v,'min_available_gib':v['min_available_kib']/1048576,'min_disk_gib':v['min_disk_bytes']/1073741824,'pagein_intervals':sum(x>0 for x in pi),'max_pagein_pages_per_sample':max(pi,default=0),'max_psi_avg10':max(psi,default=None),'psi_total_delta_us':{k:max(v)-min(v) for k,v in psi_total.items()},'max_db_cpu_percent':max(cpu,default=0),'mean_db_cpu_percent':statistics.mean(cpu) if cpu else 0}
 resources.append(row)
